/* Pixelado's characters, drawn from their pixel maps (cast_sprites.h, generated by characters/characters.py). */
#ifndef PIXELADO_CAST_H
#define PIXELADO_CAST_H

#include "pixel.h"

typedef struct { char ch; uint32_t rgb; } CastInk;

enum { CAST_NILO, CAST_LUMI, CAST_TAVO, CAST_KIRA, CAST_PIXO, CAST_PIXO_ABOUT, CAST_COUNT };   /* (Pixo: full body; _ABOUT: from the chest up, for About) */

/* the idle's length in beats: a 1-px bob and a blink, each character a few beats apart (the caller advances the beat) */
#define CAST_BEATS 8

/* draws a character with its top left at x, y, each map pixel `unit` units wide, at the given beat of its idle */
void cast_draw(PxCanvas *c, int who, float x, float y, float unit, int beat);
/* whether a character's pose differs between two beats (so a caller redraws only when something moves) */
int cast_pose(int who, int beat);

#endif
